import {writeFile} from 'node:fs/promises';
const checkedAt = new Date().toISOString();
// These are factual reading notes from web.run opens in this publication run.
// Direct fetch failures remain in fetch-results.json; browser success does not erase them.
const observations = [
  {url:'https://help.openai.com/en/articles/20001625-understanding-chatgpt-and-codex-usage-limits',sourceClass:'official',method:'web.run open; read complete help article',facts:'Starting in December, Plus, Pro and Business allowance will be shared across ChatGPT and Codex and measured in tokens. Instant chat does not draw from this allowance. Model and task affect consumption; combined remaining usage and reset times will appear in Settings > Usage. No exact December rollout day or numeric plan allowance is stated.',dateSemantics:'Observed current help text; relative updated label is not an exact first-publication date.'},
  {url:'https://help.openai.com/en/articles/20001559-understanding-card-and-device-limits-in-chatgpt',sourceClass:'official',method:'web.run open; read complete help article',facts:'Too many subscriptions tied to one card or device may block purchases. Paid-account device limits are distinct from concurrent account switching and usage limits. Go/Plus/Pro tiers count; Free and Business/Enterprise/Edu workspace plans do not count. Buying credits or resetting usage does not clear these restrictions. Help text does not give a numeric card/device cap.',dateSemantics:'Observed current help text; updated yesterday is relative metadata, not a proven launch timestamp.'},
  {url:'https://openai.com/index/astra-for-law',sourceClass:'official',method:'web.run open; read original dated product announcement',originalDate:'2026-09-17',facts:'Original Astra for Law announcement is September 17, 2026. It combines GPT-6 Astra with legal instructions and tools, starts with selected firms through Trusted Access and names gpt-6-astra-law as the API identifier. Current pricing-page appearance must not be described as first release on October31 or November1.'}
].map(x=>({...x,checkedAt,success:true,verification:'verified'}));
await writeFile('data/dev/source-archives/publication-2026-11-01/browser-reading-notes.json',JSON.stringify({runDate:'2026-11-01',checkedAt,observations},null,2)+'\n');
console.log(JSON.stringify({observations:observations.length,checkedAt}));
